sqlReaderQuery.value:
@concat('SELECT * FROM ', pipeline().parameters.table_name,
' WHERE pickup_datetime >= CAST(''', pipeline().parameters.year_month, '-01'' AS datetime2(0))',
' AND pickup_datetime < DATEADD(MONTH, 1, CAST(''', pipeline().parameters.year_month, '-01'' AS datetime2(0)))')

SELECT * FROM @{pipeline().parameters.table_name}
WHERE created_at >  '@{formatDateTime(activity('lkp_old_watermark').output.firstRow.last_value, 'yyyy-MM-dd HH:mm:ss.fff')}'
  AND created_at <= '@{formatDateTime(activity('lkp_new_watermark').output.firstRow.new_value, 'yyyy-MM-dd HH:mm:ss.fff')}'
